(function(){"use strict";const mediaBtn=document.getElementById("mediaBtn");const mediaKey="reader_cleanRead";if(mediaBtn){function updateMediaBtnState(){const isCleanRead=localStorage.getItem(mediaKey)==="true";mediaBtn.classList.toggle("media-active",!isCleanRead)}if(localStorage.getItem(mediaKey)==="true"){document.body.classList.add("clean-read")}updateMediaBtnState();mediaBtn.addEventListener("click",function(){document.body.classList.toggle("clean-read");const isCleanRead=document.body.classList.contains("clean-read");localStorage.setItem(mediaKey,isCleanRead);updateMediaBtnState()})}const bingeBtn=document.getElementById("bingeBtn");if(bingeBtn){bingeBtn.addEventListener("click",function(){window.location.href="./binge-mode.html"})}const modeToggle=document.getElementById("modeToggle");const modeKey="reader_mode";if(modeToggle){function setMode(mode){modeToggle.querySelectorAll(".option-btn").forEach(function(btn){btn.classList.toggle("active",btn.dataset.mode===mode)});if(mode==="page"){document.body.classList.remove("scrolling");document.body.classList.add("paginated")}else{document.body.classList.remove("paginated");document.body.classList.add("scrolling")}if(window.readingModeManager){window.readingModeManager.switchMode(mode)}}function initMode(){setMode("scroll")}initMode();modeToggle.addEventListener("click",function(e){var btn=e.target.closest(".option-btn");if(btn){setMode(btn.dataset.mode)}})}const textSizeToggle=document.getElementById("textSizeToggle");const textSizeKey="reader_fontSize";if(textSizeToggle){function setTextSize(size){textSizeToggle.querySelectorAll(".option-btn").forEach(function(btn){btn.classList.toggle("active",btn.dataset.size===size)});document.body.classList.remove("font-small","font-medium","font-large");document.body.classList.add("font-"+size);localStorage.setItem(textSizeKey,size)}function initTextSize(){var savedSize=localStorage.getItem(textSizeKey)||"small";setTextSize(savedSize)}initTextSize();textSizeToggle.addEventListener("click",function(e){var btn=e.target.closest(".option-btn");if(btn){setTextSize(btn.dataset.size)}})}const searchToggle=document.getElementById("searchToggle");const searchSection=document.getElementById("searchSection");const searchContent=document.getElementById("searchContent");const searchInput=document.getElementById("searchInput");if(searchToggle&&searchSection&&searchContent){searchToggle.addEventListener("click",function(){var isOpen=searchSection.classList.toggle("open");searchToggle.setAttribute("aria-expanded",isOpen);searchContent.style.display=isOpen?"block":"none";if(isOpen&&searchInput){setTimeout(function(){searchInput.focus()},100)}})}const optionsToggle=document.getElementById("optionsToggle");const optionsSection=document.getElementById("optionsSection");const optionsContent=document.getElementById("optionsContent");if(optionsToggle&&optionsSection&&optionsContent){optionsToggle.addEventListener("click",function(){var isOpen=optionsSection.classList.toggle("open");optionsToggle.setAttribute("aria-expanded",isOpen);optionsContent.style.display=isOpen?"block":"none"})}})();